          const winner = packOf2.get(ballot.order[i]);
          const loser = packOf2.get(ballot.order[j]);
          wins.set(winner, (wins.get(winner) ?? 0) + 1);
          games.set(key(winner, loser), (games.get(key(winner, loser)) ?? 0) + 1);
