      if (!medal) throw new Error("--rank is 1, 2 or 3");
      const entry = entryOrSay(snapshot, bout, ref, host);
      const mine = laneOfActor(bout, ctx.actor.id);
      if (mine && entry.properties["competition.fighter"] === mine.packId) throw new Error("a fighter never ranks its own entry");
      const group = newGroupId();
      if (opts.off) {
        await sendOp2(ctx, canvas2.id, { type: "item.react", itemId: entry.id, emoji: medal, on: false }, group);
        return ctx.json ? printJson2({ entry: entry.id, medal, on: false }) : console.log(`${medal} taken off ${entry.title}`);
      }
      for (const other of entriesOf(bout)) {
        if (other.id !== entry.id && (other.reactions?.[medal] ?? []).includes(ctx.actor.id)) {
          await sendOp2(ctx, canvas2.id, { type: "item.react", itemId: other.id, emoji: medal, on: false }, group);
        }
      }
      await sendOp2(ctx, canvas2.id, { type: "item.react", itemId: entry.id, emoji: medal, on: true }, group);
