style.command("import").description("Land somebody else's theme as this canvas's design system").argument("<file>", "a stylesheet of custom properties, or a W3C token JSON").option("--dry-run", "read it and report, without writing anything").option("--title <title>", "name for the item", "DESIGN.md").option("--in <area>", "the design system of this area only").action(
  run(async (file, opts, cmd) => {
    const ctx = await ctxOf(cmd);
    const text = await fs16.readFile(file, "utf8");
    const { tokens, problems, notes, format } = importDesign(text, path16.basename(file));
    const counts = {
      colors: Object.keys(tokens.colors ?? {}).length,
      typography: Object.keys(tokens.typography ?? {}).length,
      rounded: Object.keys(tokens.rounded ?? {}).length,
      spacing: Object.keys(tokens.spacing ?? {}).length
    };
    const total = Object.values(counts).reduce((a, b) => a + b, 0);
    if (total === 0) {
      throw new Error(
        `nothing to import from ${path16.basename(file)}${problems.length ? ` \u2014 ${problems[0]}` : ""}`
      );
    }
    const body = importedBody(path16.basename(file), tokens);
    const markdown = serializeDesign(tokens, body);
    for (const problem of problems) console.error(`note: ${problem}`);
    for (const note of notes) console.error(`note: ${note}`);
    if (opts.dryRun) {
      if (ctx.json) return printJson({ format, counts, problems, notes, markdown });
      console.log(markdown);
      console.error(
        `${format}: ${counts.colors} colours, ${counts.typography} type roles, ${counts.rounded} radii, ${counts.spacing} spacings \u2014 nothing written`
      );
      return;
    }
    const { canvas: p, snapshot } = await canvasAndSnapshot(ctx, { create: true });
    const filename = "DESIGN.md";
    const upload = await ctx.client.uploadBlob(
      p.id,
      Buffer.from(markdown, "utf8"),
      "text/markdown",
      filename
    );
    const version4 = {
      id: newVersionId(),
      blobHash: upload.blobHash,
      mimeType: "text/markdown",
      filename,
      size: upload.size
    };
    const existing2 = ownDesignSystem(snapshot, opts.in);
    if (existing2) {
      await sendOp(ctx, p.id, { type: "item.addVersion", itemId: existing2.id, version: version4 });
      if (ctx.json) return printJson({ itemId: existing2.id, format, counts, problems, notes });
      console.error(
        `${existing2.id} \u2014 design system v${existing2.versions.length + 1} from ${path16.basename(file)}`
      );
      return;
    }
    const itemId = newItemId();
    await sendOp(ctx, p.id, {
      type: "item.add",
      itemId,
      version: version4,
      width: 560,
      height: 720,
      placement: placementFor(snapshot, opts.in ? { in: opts.in } : {}),
      title: opts.title,
      properties: designSystemProperties()
    });
    if (ctx.json) return printJson({ itemId, format, counts, problems, notes });
    console.error(`${itemId} \u2014 design system for ${p.title}, imported from ${path16.basename(file)}`);
  })
);
var tool = program2.command("tool").description("Tools this canvas puts in the rail").addHelpText(
  "after",
  `
A tool is a BUTTON plus the ask it makes, and the ask is a slash command that
already exists \u2014 "an extension may only ask for what a person could ask for".
It is an ordinary item, so it versions, undoes, comments, trashes and travels
with the canvas: open somebody's canvas and their tool is on the rail, because
the tool is ON the canvas. Nothing was installed.

  { "kind": "tool", "label": "Tidy", "icon": "broom", "does": "/format" }

isocan draws it \u2014 its own component, its own tokens, its own focus ring, and
an icon from the set isocan ships. A tool cannot be off-brand, cannot be
inaccessible, and cannot do anything the vocabulary does not permit.`
);
tool.command("list", { isDefault: true }).description("Every tool on this canvas, and what each may do").action(
  run(async (_opts, cmd) => {
    const ctx = await ctxOf(cmd);
    const { canvas: p, snapshot } = await canvasAndSnapshot(ctx);
    const commands = withModuleCommands(await ctx.client.commands());
    const rows2 = [];
    for (const item of toolExtensionItems(snapshot.canvas)) {
      const version4 = item.versions.find((v) => v.id === item.currentVersionId);
      const text = version4 ? (await ctx.client.downloadBlob(p.id, version4.blobHash)).toString("utf8") : "";
      const { tool: read, problem } = readToolExtension(text, commands);
      rows2.push({
        itemId: item.id,
        title: item.title,
        ...read ? { ...read, can: toolCapabilities(read, commands) } : { problem }
      });
    }
    if (ctx.json) return printJson(rows2);
    if (rows2.length === 0) {
      return console.error("no tools on this canvas \u2014 isocan tool add <file>");
    }
    for (const row of rows2) {
      if (row.problem) {
        console.log(`${row.itemId}  ${row.title} \u2014 unavailable: ${row.problem}`);
        continue;
      }
      console.log(`${row.itemId}  ${row.label} (${row.icon}) \u2192 ${row.does}`);
      for (const can of row.can ?? []) console.log(`    ${can}`);
    }
  })
);
