    if (ctx.json) return printJson(report2);
    if (report2.landings.length === 0) {
      return console.log("the converge lane has landed nothing here yet \u2014 `node scripts/converge-night.mjs --canvas <ref>` runs one night");
    }
    const rate = report2.acceptRate === null ? "no verdicts yet" : `accept rate ${Math.round(report2.acceptRate * 100)}%`;
    console.log(`${report2.landings.length} landings \u2014 ${report2.kept} kept, ${report2.reverted} reverted, ${report2.standing} standing \xB7 ${rate}`);
    for (const l of report2.landings) {
      console.log(`  ${l.landedAt.slice(0, 16).replace("T", " ")}  ${l.status.padEnd(9)} ${l.title} (${l.itemId}) v ${l.versionId}`);
    }
