function gcLines(report2) {
  const verb = report2.dryRun ? "would sweep" : "swept";
  return {
    oplog: `${report2.retainedEntries} entries kept, ${report2.droppedEntries} ${report2.dryRun ? "would be archived" : "archived"}`,
    reachable: `${report2.reachableBlobs} blobs (${formatBytes(report2.reachableBytes)})`,
    [verb]: `${report2.sweptBlobs} blobs (${formatBytes(report2.sweptBytes)})`,
    ...report2.skippedRecentBlobs > 0 ? { "skipped (too recent)": String(report2.skippedRecentBlobs) } : {}
  };
}
program2.command("gc").description("Reclaim storage: compact the oplog and sweep unreachable blobs").option("--dry-run", "report what would be freed without deleting anything").option("--keep-ops <n>", "how many recent operations to keep undoable (default 500)").option(
  "--keep-versions <n>",
  "first prune every item's stack to its newest N versions (not undoable; needs --force)"
).option("--force", "confirm --keep-versions").option("--all", "sweep every canvas you are admitted to at this home, not just this one").action(
  run(
    async (opts, cmd) => {
      const ctx = await ctxOf(cmd);
      const request = {
        ...opts.dryRun ? { dryRun: true } : {},
        ...opts.keepOps !== void 0 ? { keepOps: Number(opts.keepOps) } : {}
      };
      if (opts.keepVersions !== void 0) {
        const keep = Number(opts.keepVersions);
        if (!Number.isInteger(keep) || keep < 1) {
          throw new Error(`--keep-versions wants a whole number of at least 1, not "${opts.keepVersions}"`);
        }
        if (opts.all) throw new Error("--keep-versions prunes one canvas \u2014 drop --all, or run it per canvas");
        const { canvas: p2, snapshot } = await canvasAndSnapshot(ctx);
        const work = Object.values(snapshot.canvas.items).map((item) => ({ item, dropping: prunedVersions(item, keep).length })).filter(({ dropping: dropping2 }) => dropping2 > 0);
        const dropping = work.reduce((n, w) => n + w.dropping, 0);
        if (dropping > 0 && !opts.dryRun) {
          if (!opts.force) {
            throw new Error(
              `pruning ${dropping} version${dropping === 1 ? "" : "s"} across ${work.length} item${work.length === 1 ? "" : "s"} is not undoable \u2014 re-run with --force`
            );
          }
          for (const { item } of work) {
            await sendOp(ctx, p2.id, { type: "item.pruneVersions", itemId: item.id, keep });
          }
        }
        if (!ctx.json) {
          console.log(
            opts.dryRun ? `would prune ${dropping} version${dropping === 1 ? "" : "s"} across ${work.length} item${work.length === 1 ? "" : "s"}` : `pruned ${dropping} version${dropping === 1 ? "" : "s"} across ${work.length} item${work.length === 1 ? "" : "s"}`
          );
        }
      }
      if (opts.all) {
        const home = await ctx.client.gcHome(request);
        if (ctx.json) return printJson(home);
        printTable(
          home.canvases.map((row) => ({
            canvas: row.canvasId,
            // A canvas that threw is a row, not a missing row: the sweep went
            // on without it, and the thing worth seeing is which one it was.
            swept: row.report ? `${row.report.sweptBlobs} blobs (${formatBytes(row.report.sweptBytes)})` : `failed: ${row.error ?? "unknown"}`,
            archived: row.report ? String(row.report.droppedEntries) : ""
          }))
        );
        console.log("");
        return printKeyValues({
          canvases: String(home.canvases.length),
          ...gcLines(home.totals)
        });
      }
      const p = await resolveCanvas(ctx);
      const report2 = await ctx.client.gc(p.id, request);
      if (ctx.json) return printJson(report2);
      printKeyValues(gcLines(report2));
    }
  )
);
