async function currentText(ctx, canvasId, item) {
  const version4 = item.versions.find((v) => v.id === item.currentVersionId) ?? item.versions.at(-1);
  return version4 ? (await ctx.client.downloadBlob(canvasId, version4.blobHash)).toString("utf8") : "";
}
async function intrinsicSize(ctx, canvasId, item) {
  const version4 = item.versions.find((v) => v.id === item.currentVersionId) ?? item.versions.at(-1);
  if (!version4) return null;
  const cap = (w, h) => ({
    width: Math.max(80, Math.min(2400, Math.round(w))),
    height: Math.max(80, Math.min(2400, Math.round(h)))
  });
  if (version4.mimeType === "image/svg+xml") {
    const bytes = await ctx.client.downloadBlob(canvasId, version4.blobHash);
    const box = drawingViewBox(bytes.toString("utf8"));
    return box ? cap(box.maxX - box.minX, box.maxY - box.minY) : null;
  }
  if (version4.mimeType === "image/png" || version4.mimeType === "image/jpeg") {
    const bytes = await ctx.client.downloadBlob(canvasId, version4.blobHash);
    const size = version4.mimeType === "image/png" ? pngSize(bytes) : jpegSize(bytes);
    return size ? cap(size.width, size.height) : null;
  }
  return null;
}
function pngSize(b) {
  if (b.length < 24 || b[1] !== 80 || b[2] !== 78 || b[3] !== 71) return null;
  const view = new DataView(b.buffer, b.byteOffset, b.byteLength);
  return { width: view.getUint32(16), height: view.getUint32(20) };
}
function jpegSize(b) {
  if (b.length < 4 || b[0] !== 255 || b[1] !== 216) return null;
  let i = 2;
  while (i + 9 < b.length) {
    if (b[i] !== 255) return null;
    const marker = b[i + 1];
    const length = b[i + 2] << 8 | b[i + 3];
    if (marker >= 192 && marker <= 207 && ![196, 200, 204].includes(marker)) {
      return { height: b[i + 5] << 8 | b[i + 6], width: b[i + 7] << 8 | b[i + 8] };
    }
    i += 2 + length;
  }
  return null;
}
